const rawJson = $("Code in JavaScript").first().json;
const body = rawJson.body || rawJson;

const message = (body.message || "").trim();
const sessionId = rawJson.sessionId || body.sessionId;
const category = body.category || "simulador";

const procesosValidos = [
  // Investigación
  "Investigación Formativa",
  //"I+D+I+C",
  //"Gestión Editorial",
  "Transferencia de Conocimiento y Tecnología",
  // Proyección Social
  "Educación Continua",
  //"Gestión de Empleabilidad",
  //"Práctica Profesional",
  //"Práctica en Responsabilidad Social",
  //"Voluntariado",
  //"Relacionamiento con Egresados y Egresados no Graduados",
  //"Articulación",
  //"Gestión y Desarrollo del Emprendimiento",
  // Docencia
  "Enseñanza, Aprendizaje y Evaluación",
  "Vida Estudiantil",
  //"Desarrollo Curricular",
  // GAF
  "Gestión de Ingresos",
  //"Planeación Financiera y Presupuesto",
  //"Contabilidad Financiera y Costeo",
  "Aprovisionamiento",
  //"Administración de Tesorería",
  //"Gestión Documental",
  //"Gestión Académico Administrativo",
  // GMP
  //"Investigación de Mercados",
  "Comercialización y Ventas"
];

const messageEsProceso = procesosValidos.includes(message);
const procesoDesdeBody = procesosValidos.includes(body.proceso) ? body.proceso : null;

let procesoFinal = lecturaDB.proceso
  || procesoDesdeBody
  || (messageEsProceso ? message : null);

let macroFinal = lecturaDB.macroproceso
  || body.macroproceso
  || null;

const esSeleccionDeProceso = messageEsProceso && !lecturaDB.proceso;

const sanitizedMessage = esSeleccionDeProceso
  ? `El usuario ha iniciado la auditoría del subproceso "${procesoFinal}" perteneciente al macroproceso "${macroFinal}". Salúdalo brevemente y formula la primera pregunta técnica de auditoría externa basada en ISO 9001:2015 para ese subproceso.`
  : message;

// ── CONTADOR DE FASES ──────────────────────────────────────
const clausulaActual = lecturaDB.clausula_actual || null;
const fasesCompletadas = lecturaDB.fases_completadas || [];
const conteoIntercambios = esSeleccionDeProceso
  ? 0
  : (lecturaDB.conteo_intercambios_clausula || 0) + 1;
// ──────────────────────────────────────────────────────────

return [{ json: {
  sessionId,
  category,
  proceso_activo: procesoFinal,
  macroproceso_activo: macroFinal,
  sanitizedMessage,
  debeSeleccionarProceso: !procesoFinal,
  esSeleccionDeProceso,
  // Contador de fases
  clausula_actual: clausulaActual,
  fases_completadas: fasesCompletadas,
  conteo_intercambios_clausula: conteoIntercambios,
  // Debug
  _debug_db_proceso: lecturaDB.proceso || null,
  _debug_message: message,
  _debug_body_proceso: body.proceso || null
}}];

return [{
  json: {
    respuesta: "Por favor selecciona un subproceso válido desde el menú de auditoría."
  }
}];

