const outputAI = $('AI Agent Orquestador').first().json.output || '';
const sessionId = $('Code - Determinar Estado').first().json.sessionId;
const fasesActuales = $('Code - Determinar Estado').first().json.fases_completadas || [];

// Detectar si el evaluador completó alguna fase en este intercambio
let fasesNuevas = [...fasesActuales];

if (outputAI.includes('FASE 1') || outputAI.toLowerCase().includes('comprensión')) {
  if (!fasesNuevas.includes('FASE_1')) fasesNuevas.push('FASE_1');
}
if (outputAI.includes('FASE 2') || outputAI.toLowerCase().includes('verificación de control')) {
  if (!fasesNuevas.includes('FASE_2')) fasesNuevas.push('FASE_2');
}
if (outputAI.includes('FASE 3') || outputAI.toLowerCase().includes('coherencia documental')) {
  if (!fasesNuevas.includes('FASE_3')) fasesNuevas.push('FASE_3');
}

// Detectar si AVA avanzó a nueva cláusula — resetear fases
const avanzoClausiula = outputAI.toLowerCase().includes('avanzamos a la cláusula') ||
                        outputAI.toLowerCase().includes('siguiente cláusula');

if (avanzoClausiula) {
  fasesNuevas = [];
}

// Extraer número de cláusula del output si aparece
const clausulaMatch = outputAI.match(/cláusula\s+(\d+\.\d+(?:\.\d+)?)/i);
const clausulaDetectada = clausulaMatch ? clausulaMatch[1] : 
  $('Code - Determinar Estado').first().json.clausula_actual;

// Actualizar en Supabase
await this.helpers.httpRequest({
  method: 'PATCH',
  url: 'https://hzgoxdpvlvzxzwoefeui.supabase.co/rest/v1/chat_sessions',
  headers: {
    'Content-Type': 'application/json',
    'apikey': 'sb_secret_tR7D4YA3ds7CC9OSLM9CPQ_aMZJiPpZ',
    'Authorization': 'Bearer sb_secret_tR7D4YA3ds7CC9OSLM9CPQ_aMZJiPpZ',
    'Prefer': 'return=minimal'
  },
  body: {
    clausula_actual: clausulaDetectada,
    fases_completadas: fasesNuevas
  },
  qs: { session_id: `eq.${sessionId}` },
  json: true
});

return [{
  json: {
    ...$('AI Agent Orquestador').first().json,
    clausula_actual: clausulaDetectada,
    fases_completadas: fasesNuevas
  }
}];
